package com.corebalt.isp.network.domain;

import java.math.BigInteger;
import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.PrivateKey;
import java.security.PublicKey;
import java.security.SecureRandom;
import java.security.spec.NamedParameterSpec;
import java.security.spec.XECPrivateKeySpec;
import java.security.spec.XECPublicKeySpec;
import java.util.Base64;
import javax.crypto.KeyAgreement;

/**
 * WireGuard key pairs for routers (ADR 0013): generated by the platform, the private key handed over
 * once in the onboarding script, only the public key kept. A WireGuard key is 32 bytes in base64;
 * the private key is a clamped Curve25519 scalar (RFC 7748) and the public key is X25519 of it with
 * the base point 9, which is what {@code wg pubkey} computes.
 */
public final class WireGuardKeys {

    public record Pair(String privateKey, String publicKey) {}

    private static final SecureRandom RANDOM = new SecureRandom();
    private static final NamedParameterSpec X25519 = NamedParameterSpec.X25519;

    private WireGuardKeys() {}

    public static Pair generate() {
        final byte[] scalar = new byte[32];
        RANDOM.nextBytes(scalar);
        final byte[] clamped = clamp(scalar);
        return new Pair(Base64.getEncoder().encodeToString(clamped), publicKeyOf(clamped));
    }

    /** The public key (base64) of a private key (base64), as {@code wg pubkey} would print it. */
    public static String publicKeyOf(final String privateKeyBase64) {
        return publicKeyOf(Base64.getDecoder().decode(privateKeyBase64));
    }

    static String publicKeyOf(final byte[] scalar) {
        if (scalar.length != 32) {
            throw new IllegalArgumentException("a WireGuard key is 32 bytes");
        }
        try {
            final KeyFactory factory = KeyFactory.getInstance("XDH");
            final PrivateKey priv = factory.generatePrivate(new XECPrivateKeySpec(X25519, scalar));
            final PublicKey base = factory.generatePublic(new XECPublicKeySpec(X25519, BigInteger.valueOf(9)));
            final KeyAgreement x25519 = KeyAgreement.getInstance("XDH");
            x25519.init(priv);
            x25519.doPhase(base, true);
            return Base64.getEncoder().encodeToString(x25519.generateSecret());
        } catch (final GeneralSecurityException e) {
            throw new IllegalStateException("X25519 is not available", e);
        }
    }

    /** RFC 7748 decodeScalar25519: what every X25519 implementation does to a scalar before using it. */
    public static byte[] clamp(final byte[] scalar) {
        final byte[] out = scalar.clone();
        out[0] &= (byte) 248;
        out[31] &= (byte) 127;
        out[31] |= (byte) 64;
        return out;
    }
}
